content:
[
  {
    "id": "ctxuse_001",
    "user_command": "라이다 기준 전방 3m 내 장애물 확인",
    "context": {
      "robot": "go2_edu",
      "available_apps": ["lidar_app", "detection_app", "tts_app"],
      "sensors": ["lidar_front", "rgb_front"],
      "topics": ["/scan/front"]
    },
    "expected_api_plan": [
      {"app": "lidar_app", "api": "get_scan", "topic": "/scan/front"},
      {"app": "detection_app", "api": "detect_obstacles", "range_m": 3.0},
      {"app": "tts_app", "api": "speak", "message_type": "obstacle_report"}
    ],
    "expected_response_style": "short_military_report"
  },
  {
    "id": "ctxuse_002",
    "user_command": "맵에서 회의실A 좌표 찾아 현재 위치 기준 거리 보고",
    "context": {
      "robot": "go2_edu",
      "available_apps": ["map_app", "odom_app", "nav_math_app", "tts_app"],
      "map_frame": "map",
      "named_locations": ["meeting_room_A"]
    },
    "expected_api_plan": [
      {"app": "map_app", "api": "resolve_location", "name": "meeting_room_A"},
      {"app": "odom_app", "api": "get_pose", "frame": "map"},
      {"app": "nav_math_app", "api": "compute_distance"},
      {"app": "tts_app", "api": "speak", "message_type": "distance_report"}
    ],
    "expected_response_style": "short_military_report"
  },
  {
    "id": "ctxuse_003",
    "user_command": "odom이 끊기면 visual odom으로 대체해서 위치 보고",
    "context": {
      "robot": "go2_edu",
      "available_apps": ["odom_app", "vslam_app", "tts_app"],
      "topics": ["/odom", "/vslam/odom"],
      "fallback_policy": "use_vslam_if_odom_unavailable"
    },
    "expected_api_plan": [
      {"app": "odom_app", "api": "get_pose", "topic": "/odom"},
      {"app": "vslam_app", "api": "get_pose", "topic": "/vslam/odom", "fallback": true},
      {"app": "tts_app", "api": "speak", "message_type": "pose_report"}
    ],
    "expected_response_style": "short_military_report"
  },
  {
    "id": "ctxuse_004",
    "user_command": "카메라 프레임이 10fps 미만이면 탐지 신뢰도 낮춤",
    "context": {
      "robot": "go2_edu",
      "available_apps": ["camera_app", "detection_app", "tts_app"],
      "sensor_limits": {"camera_min_fps": 10}
    },
    "expected_api_plan": [
      {"app": "camera_app", "api": "get_stream_status"},
      {"app": "camera_app", "api": "get_latest_frame"},
      {"app": "detection_app", "api": "detect_objects", "confidence_mode": "adaptive"},
      {"app": "tts_app", "api": "speak", "message_type": "confidence_aware_report"}
    ],
    "expected_response_style": "short_military_report"
  },
  {
    "id": "ctxuse_005",
    "user_command": "금지구역 레이어 반영해서 B통로 경유 경로 계획",
    "context": {
      "robot": "go2_edu",
      "available_apps": ["map_app", "navigation_app", "tts_app"],
      "map_layers": ["base", "no_go", "dynamic_obstacle"],
      "named_locations": ["B_corridor"]
    },
    "expected_api_plan": [
      {"app": "map_app", "api": "load_layer", "layer": "no_go"},
      {"app": "map_app", "api": "resolve_location", "name": "B_corridor"},
      {"app": "navigation_app", "api": "plan_route", "destination": "B_corridor", "respect_no_go": true},
      {"app": "tts_app", "api": "speak", "message_type": "route_report"}
    ],
    "expected_response_style": "short_military_report"
  },
  {
    "id": "ctxuse_006",
    "user_command": "IMU 기울기 15도 이상이면 이동 중지",
    "context": {
      "robot": "go2_edu",
      "available_apps": ["imu_app", "safety_app", "tts_app"],
      "topics": ["/imu/data"],
      "thresholds": {"tilt_deg": 15}
    },
    "expected_api_plan": [
      {"app": "imu_app", "api": "get_tilt", "topic": "/imu/data"},
      {"app": "safety_app", "api": "conditional_stop", "condition": "tilt_over_threshold"},
      {"app": "tts_app", "api": "speak", "message_type": "safety_report"}
    ],
    "expected_response_style": "short_military_report"
  },
  {
    "id": "ctxuse_007",
    "user_command": "현재 맵 프레임과 odom 프레임 불일치 검사",
    "context": {
      "robot": "go2_edu",
      "available_apps": ["tf_app", "odom_app", "map_app", "tts_app"],
      "frames": ["map", "odom", "base_link"]
    },
    "expected_api_plan": [
      {"app": "map_app", "api": "get_frame_id"},
      {"app": "odom_app", "api": "get_frame_id"},
      {"app": "tf_app", "api": "check_transform_consistency"},
      {"app": "tts_app", "api": "speak", "message_type": "frame_consistency_report"}
    ],
    "expected_response_style": "short_military_report"
  },
  {
    "id": "ctxuse_008",
    "user_command": "열화상 센서 있으면 사람 탐지를 열화상 우선으로",
    "context": {
      "robot": "go2_edu",
      "available_apps": ["thermal_app", "camera_app", "detection_app", "tts_app"],
      "sensors": ["thermal_front", "rgb_front"],
      "policy": "prefer_thermal_for_human_detection"
    },
    "expected_api_plan": [
      {"app": "thermal_app", "api": "get_latest_frame"},
      {"app": "detection_app", "api": "detect_objects", "target": "person", "sensor": "thermal_front"},
      {"app": "tts_app", "api": "speak", "message_type": "detection_report"}
    ],
    "expected_response_style": "short_military_report"
  },
  {
    "id": "ctxuse_009",
    "user_command": "네트워크 지연 200ms 초과 시 원격 명령 실행 보류",
    "context": {
      "robot": "go2_edu",
      "available_apps": ["network_app", "safety_app", "tts_app"],
      "thresholds": {"latency_ms": 200}
    },
    "expected_api_plan": [
      {"app": "network_app", "api": "get_latency"},
      {"app": "safety_app", "api": "gate_remote_command", "condition": "latency_over_threshold"},
      {"app": "tts_app", "api": "speak", "message_type": "network_safety_report"}
    ],
    "expected_response_style": "short_military_report"
  },
  {
    "id": "ctxuse_010",
    "user_command": "야간 모드면 카메라 노출 자동 조정 후 탐지",
    "context": {
      "robot": "go2_edu",
      "available_apps": ["camera_app", "detection_app", "tts_app"],
      "environment": {"lighting": "night"}
    },
    "expected_api_plan": [
      {"app": "camera_app", "api": "set_exposure_mode", "mode": "low_light_auto"},
      {"app": "camera_app", "api": "get_latest_frame"},
      {"app": "detection_app", "api": "detect_objects", "target": "person"},
      {"app": "tts_app", "api": "speak", "message_type": "night_detection_report"}
    ],
    "expected_response_style": "short_military_report"
  }
]
